/** Leftover patterns reported by --check (and by the final sweep). */
export const LEFTOVER = /mcallen|9565865646|586[-. ]?5646|7913 N(?:orth)? 10th|7913\+N|78504|northmcallen|snoozemcallen|ChIJBYBxOXChZYYR48f71GAS7YY|Rio Grande|Winter Texan|tamalada|quincea|Hidalgo|\bTX\b|Texas|America\/Chicago|Edinburg|Pharr|\bMission\b|Brownsville|Harlingen|Monterrey|South Texas|the Valley|el Valle|Su 12:00-18:00|Sun 12[ –-]+6|12[ –-]+6 PM|684480ff2c95c570cfc22e24|6a7578249a9c7792ea5a8b22|699c969010bc9c1e4d659063|69a1cbdf917b4b217201b5ff|69a601e75a52f4e92a27dcf5/g;
/** Leftovers that are expected: the stage-1 mapping and the McAllen-era tooling (kept as documentation), the converter's
    clone hosts, a stock photo URL. */
export const LEFTOVER_OK = /scripts\/relocate\.mjs|scripts\/audit-location\.mjs|scripts\/brand-nap\.mjs|scripts\/relocate-castle-rock\.mjs|scripts\/post-build\.mjs|brownsville-webiste|brownsville\.snoozemattresscompany\.com|C:\/clones\/brownsville|unsplash\.com\/photo-1597852075012|README\.md/;

const SKIP_DIRS = new Set(['node_modules', '.next', '.git', '.vercel', 'verify-out', 'out', 'assets', 'ghl-stub', 'chunks', 'docs']);
const SKIP_FILES = new Set(['relocate.mjs', 'relocate-castle-rock.mjs', 'audit-location.mjs', 'brand-nap.mjs', 'reviews-widget.mjs', 'integrations.mjs', 'post-build.mjs', 'asset-map.json', 'conversion-report.json', 'tsconfig.tsbuildinfo', 'package-lock.json', 'README.md', 'segments.json', 'missing.json']);
const TEXT = /\.(ts|tsx|mjs|js|json|html|css)$/;
const DICT = /^es(\.part-\d+|\.extra)\.json$/; // overrides/i18n dictionaries: values only

function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (SKIP_DIRS.has(e.name)) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (TEXT.test(e.name) && !SKIP_FILES.has(e.name)) out.push(p);
  }
  return out;
}

export function applyRules(text) {
  let out = text;
  for (const [re, to] of RULES) out = out.replace(re, to);
  return out;
}

function relocateFile(file, check) {
  const rel = path.relative(ROOT, file).replace(/\\/g, '/');
  const src = fs.readFileSync(file, 'utf8');
  let next;
  if (DICT.test(path.basename(file)) && rel.startsWith('overrides/i18n/')) {
    const dict = JSON.parse(src);
    for (const k of Object.keys(dict)) if (typeof dict[k] === 'string') dict[k] = applyRules(dict[k]);
    for (const k of Object.keys(dict)) { const nk = applyRules(k); if (nk !== k && !(nk in dict) && typeof dict[k] === 'string') dict[nk] = dict[k]; }
    const indent = (src.match(/^\{\r?\n(\s+)"/) || [, ' '])[1].length;
    next = JSON.stringify(dict, null, indent) + (src.endsWith('\n') ? '\n' : '');
  } else {
    next = applyRules(src);
  }
  if (next !== src && !check) fs.writeFileSync(file, next);
  return next !== src ? rel : null;
}

export function leftovers(text, rel = '') {
  const found = [];
  if (LEFTOVER_OK.test(rel)) return found;
  let m;
  const re = new RegExp(LEFTOVER.source, 'gi');
  while ((m = re.exec(text))) {
    const ctx = text.slice(Math.max(0, m.index - 50), m.index + m[0].length + 50).replace(/\s+/g, ' ');
    if (!LEFTOVER_OK.test(ctx)) found.push(ctx);
  }
  return found;
}

export function relocateCastleRock(root = ROOT, { check = false, quiet = false } = {}) {
  const changed = [];
  const left = {};
  for (const f of walk(root)) {
    const c = relocateFile(f, check);
    if (c) changed.push(c);
    const rel = path.relative(root, f).replace(/\\/g, '/');
    const text = DICT.test(path.basename(f)) ? Object.values(JSON.parse(fs.readFileSync(f, 'utf8'))).join('\n') : fs.readFileSync(f, 'utf8');
    const l = leftovers(text, rel);
    if (l.length) left[rel] = l;
  }
  if (!quiet) {
    console.log(`relocate-castle-rock: ${check ? 'would change' : 'changed'} ${changed.length} file(s)`);
    const files = Object.keys(left);
    if (files.length) {
      console.log(`relocate-castle-rock: ${files.length} file(s) still mention the old location:`);
      for (const f of files) { console.log(`  ${f}: ${left[f].length} hit(s)`); for (const c of left[f].slice(0, 4)) console.log(`      …${c}…`); }
    } else console.log('relocate-castle-rock: no leftovers');
  }
  return { changed, leftovers: left };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  relocateCastleRock(ROOT, { check: process.argv.includes('--check') });
}
